int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data, const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio = NULL;
    struct bio *last = NULL;
    int ret = 0;

    if (!iov_iter_count(iter))
        return -EINVAL;

    while (iov_iter_count(iter)) {
        struct bio *b;
        ssize_t bytes;

        b = bio_alloc(GFP_NOIO, 1);
        if (!b) {
            ret = -EINVAL;
            goto unmap;
        }

        bytes = bio_set_pages(b, iter, 1 << (PAGE_SHIFT - 9), 0);
        if (bytes <= 0) {
            bio_put(b);
            ret = -EINVAL;
            goto unmap;
        }

        if (bio_add_page(b, iter->iov->iov_base, bytes, 0) != bytes) {
            bio_put(b);
            ret = -EINVAL;
            goto unmap;
        }

        if (last)
            last->bi_next = b;
        else
            rq->biotchain = b;

        last = b;
        iov_iter_advance(iter, bytes);
    }

    rq->cmd_flags |= REQ_USER_MAPPED;

    return 0;

unmap:
    while ((bio = rq->biotchain)) {
        rq->biotchain = bio->bi_next;
        bio_put(bio);
    }

    return ret;
}

int map_user_io_vectors(struct request_queue *q, struct request *rq,
                        struct rq_map_data *map_data,
                        const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio = NULL;
    struct bio *prev_bio = NULL;
    struct bio_vec bvec;
    struct iovec *iov;
    unsigned int nr_segs = 0;
    size_t iov_offset = 0;
    int ret = 0;
    int i;

    if (!iov_iter_count(iter))
        return -EINVAL;

    iov = iter->iov;

    for (i = 0; i < iter->nr_segs; i++) {
        size_t seg_len = iov->iov_len;
        unsigned long align_mask = queue_dma_alignment(q);
        unsigned long phys_addr;
        void *vaddr;

        vaddr = iov->iov_base + iov_offset;
        phys_addr = (unsigned long)virt_to_phys(vaddr);
        if ((unsigned long)vaddr & align_mask || !IS_ALIGNED(seg_len, 512)) {
            bio = bio_kmalloc(gfp_mask, 1);
            if (!bio) {
                ret = -EINVAL;
                goto error;
            }
            bio->bi_end_io = NULL;
            bio_add_page(bio, virt_to_page(vaddr), seg_len, offset_in_page(vaddr));
            if (prev_bio)
                prev_bio->bi_next = bio;
            else
                rq->bio = bio;
            prev_bio = bio;
        } else {
            if (map_data) {
                bio = bio_map_user(q->dma_ops, map_data->dm_dev, vaddr, seg_len, iter->data_dir);
                if (IS_ERR(bio)) {
                    ret = PTR_ERR(bio);
                    goto error;
                }
                if (prev_bio)
                    prev_bio->bi_next = bio;
                else
                    rq->bio = bio;
                prev_bio = bio;
            } else {
                ret = -EINVAL;
                goto error;
            }
        }
        iov_offset += seg_len;
        iov++;
        nr_segs++;
    }

    if (nr_segs) {
        rq->nr_phys_segments = nr_segs;
        if (iter->data_dir == READ)
            rq->cmd_flags |= REQ_DRV_READ;
        else
            rq->cmd_flags |= REQ_DRV_WRITE;
    }

    return 0;

error:
    if (rq->bio)
        bio_unmap_user(rq->bio, iter->data_dir);
    return ret;
}

int map_user_iovecs(struct request_queue *q, struct request *rq, struct rq_map_data *map_data, const struct iov_iter *iter, gfp_t gfp_mask) {
    struct bio *bio = NULL;
    int ret = 0;
    size_t bytes_mapped = 0;

    if (!iter || iov_iter_alignment(iter) || iov_iter_is_bvec(iter)) {
        return -EINVAL;
    }

    while (iov_iter_count(iter)) {
        struct bio *new_bio;
        int nr_segs;

        new_bio = bio_alloc(gfp_mask, 0);
        if (!new_bio) {
            ret = -EINVAL;
            goto unmap_error;
        }

        nr_segs = bio_iov_iter_get_pages(new_bio, iter, min(iov_iter_count(iter), (size_t)BIO_MAX_PAGES), 0);
        if (nr_segs <= 0) {
            bio_put(new_bio);
            ret = -EINVAL;
            goto unmap_error;
        }

        new_bio->bi_iter = iter->iov;
        new_bio->bi_bdev = rq->q->backing_dev_info->bi_bdev;
        new_bio->bi_end_io = NULL;

        if (!bio) {
            bio = new_bio;
        } else {
            rq->biotail->bi_next = new_bio;
        }
        rq->biotail = new_bio;
    }

    if (!bio) {
        return -EINVAL;
    }

    rq->cmd_flags |= (REQ_MAP_DATA | REQ_UNPLUG);
    return 0;

unmap_error:
    while (bio) {
        struct bio *next = bio->bi_next;
        bio_put(bio);
        bio = next;
    }
    return ret;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data, const struct iov_iter *iter, gfp_t gfp_mask) {
    size_t total_size = iov_iter_count(iter);
    struct bio *bio = NULL;
    int ret = 0;

    if (!iter || !iov_iter_count(iter))
        return -EINVAL;

    while (iov_iter_count(iter)) {
        struct bio *new_bio;
        unsigned int nr_segs;
        ssize_t len;

        len = min(iov_iter_count(iter), (size_t) queue_max_hw_sectors(q) << 9);
        if (len <= 0)
            break;

        new_bio = bio_alloc(gfp_mask, 1);
        if (!new_bio) {
            ret = -EINVAL;
            goto error;
        }

        nr_segs = bio_add_pc_page(q, new_bio, iov_iter_page(iter), len, iov_iter_pos(iter));
        if (!nr_segs) {
            bio_put(new_bio);
            ret = -EINVAL;
            goto error;
        }

        iov_iter_advance(iter, len);

        if (!bio) {
            bio = new_bio;
        } else {
            rq->biotail->bi_next = new_bio;
            rq->biotail = new_bio;
        }

        rq->biotail = new_bio;
    }

    if (!bio)
        return -EINVAL;

    rq->__data_len = total_size;
    rq->nr_phys_segments = 1;
    rq->cmd_flags |= REQ_USER_MAPPED;

    return 0;

error:
    if (bio)
        bio_unmap_user(bio);
    return ret;
}

int blk_rq_map_user_iov(struct request_queue *q, struct request *rq,
                        struct rq_map_data *map_data,
                        const struct iov_iter *iter, gfp_t gfp_mask)
{
    int ret = 0;
    struct bio *bio = NULL;

    if (!iov_iter_count(iter))
        return -EINVAL;

    if (!map_data || !map_data->offset)
        return -EINVAL;

    while (iov_iter_count(iter)) {
        struct bio *new_bio;
        unsigned int nr_segs = min(INDIRECT_BLOCK_COUNT, iov_iter_segments(iter));
        size_t len = iov_iter_count(iter);

        new_bio = bio_alloc(gfp_mask, nr_segs);
        if (!new_bio) {
            ret = -ENOMEM;
            goto unmap;
        }

        ret = __blk_rq_map_user_iov(q, rq, map_data, iter, new_bio, len);
        if (ret)
            goto unmap;

        if (bio)
            bio_chain(bio, new_bio);
        else
            rq->bio = new_bio;
        bio = new_bio;
    }

    return 0;

unmap:
    if (bio)
        bio_unmap_user(bio);
    return ret;
}
